input.content:
import * as THREE from 'three'
import { isLiquid, isSolid } from './blocks.js'
import { WORLD_HEIGHT } from './worldgen.js'

const HALF_WIDTH = 0.3
const HEIGHT = 1.8
const EYE_HEIGHT = 1.62
const GRAVITY = 28
const JUMP_SPEED = 8.7
const WALK_SPEED = 4.7
const SPRINT_SPEED = 7.3
const FLY_SPEED = 10.5
const FLY_SPRINT_SPEED = 17

export class Player {
  constructor(world, camera, domElement) {
    this.world = world
    this.camera = camera
    this.dom = domElement
    this.position = new THREE.Vector3(0.5, 40, 0.5)
    this.velocity = new THREE.Vector3()
    this.yaw = 0
    this.pitch = 0
    this.onGround = false
    this.flying = false
    this.inWater = false
    this.headInWater = false
    this.sprinting = false
    this.enabled = false
    this.keys = new Set()
    this.joystick = { x: 0, y: 0 }
    this.touchJump = false
    this.lastSpace = 0
    this.stepDistance = 0
    this.spawn = { x: 0.5, y: 40, z: 0.5, yaw: 0, pitch: 0 }
    this.callbacks = {}
    this._bindKeys()
  }

  _bindKeys() {
    window.addEventListener('keydown', (event) => {
      if (!this.enabled) return
      if (event.code === 'Space' || event.code.startsWith('Arrow')) event.preventDefault()
      if (event.repeat) return

      if (event.code === 'Space') {
        const now = performance.now()
        if (now - this.lastSpace < 280) {
          this.toggleFly()
          this.lastSpace = 0
        } else {
          this.lastSpace = now
        }
      }
      if (event.code === 'KeyF') this.toggleFly()
      this.keys.add(event.code)
    })

    window.addEventListener('keyup', (event) => {
      this.keys.delete(event.code)
    })

    window.addEventListener('blur', () => {
      this.keys.clear()
      this.joystick.x = 0
      this.joystick.y = 0
      this.touchJump = false
    })
  }

  setSpawn(x, y, z, yaw = 0, pitch = 0) {
    this.spawn = { x: x + 0.5, y: y + 0.001, z: z + 0.5, yaw, pitch }
    this.respawn()
  }

  respawn() {
    this.position.set(this.spawn.x, this.spawn.y, this.spawn.z)
    this.velocity.set(0, 0, 0)
    this.yaw = this.spawn.yaw
    this.pitch = this.spawn.pitch
    this.flying = false
    this.onGround = false
  }

  toggleFly() {
    this.flying = !this.flying
    this.velocity.y = 0
    this.callbacks.onFly?.(this.flying)
  }

  setJoystick(x, y) {
    this.joystick.x = x
    this.joystick.y = y
  }

  look(dx, dy, sensitivity = 0.0022) {
    this.yaw -= dx * sensitivity
    this.pitch -= dy * sensitivity
    this.pitch = Math.max(-1.54, Math.min(1.54, this.pitch))
  }

  update(dt) {
    if (!this.enabled) return
    dt = Math.min(dt, 0.05)

    const forwardInput =
      (this.keys.has('KeyW') || this.keys.has('ArrowUp') ? 1 : 0) -
      (this.keys.has('KeyS') || this.keys.has('ArrowDown') ? 1 : 0) -
      this.joystick.y
    const strafeInput =
      (this.keys.has('KeyD') || this.keys.has('ArrowRight') ? 1 : 0) -
      (this.keys.has('KeyA') || this.keys.has('ArrowLeft') ? 1 : 0) +
      this.joystick.x
    const wantsJump = this.keys.has('Space') || this.touchJump
    this.sprinting = (this.keys.has('ShiftLeft') || this.keys.has('ShiftRight')) && !this.flying

    const sin = Math.sin(this.yaw)
    const cos = Math.cos(this.yaw)
    let dirX = -sin * forwardInput + cos * strafeInput
    let dirZ = -cos * forwardInput - sin * strafeInput
    const length = Math.hypot(dirX, dirZ)
    if (length > 1) {
      dirX /= length
      dirZ /= length
    }

    const feetBlock = this.world.getBlock(
      Math.floor(this.position.x),
      Math.floor(this.position.y + 0.2),
      Math.floor(this.position.z)
    )
    const headBlock = this.world.getBlock(
      Math.floor(this.position.x),
      Math.floor(this.position.y + EYE_HEIGHT),
      Math.floor(this.position.z)
    )
    this.inWater = isLiquid(feetBlock)
    this.headInWater = isLiquid(headBlock)

    let speed
    if (this.flying) speed = this.keys.has('ShiftLeft') || this.keys.has('ShiftRight') ? FLY_SPRINT_SPEED : FLY_SPEED
    else if (this.inWater) speed = 3.3
    else speed = this.sprinting ? SPRINT_SPEED : WALK_SPEED

    const targetX = dirX * speed
    const targetZ = dirZ * speed
    const response = this.flying ? 8 : this.onGround ? 15 : this.inWater ? 6 : 2.2
    const blend = 1 - Math.exp(-response * dt)
    this.velocity.x += (targetX - this.velocity.x) * blend
    this.velocity.z += (targetZ - this.velocity.z) * blend

    if (this.flying) {
      const lift = (wantsJump ? 1 : 0) - (this.keys.has('ShiftLeft') || this.keys.has('ShiftRight') ? 1 : 0)
      this.velocity.y += (lift * FLY_SPEED - this.velocity.y) * (1 - Math.exp(-10 * dt))
    } else if (this.inWater) {
      this.velocity.y -= 9 * dt
      this.velocity.y = Math.max(this.velocity.y, -3.2)
      if (wantsJump) this.velocity.y = 4.4
    } else {
      this.velocity.y -= GRAVITY * dt
      this.velocity.y = Math.max(this.velocity.y, -45)
      if (wantsJump && this.onGround) {
        this.velocity.y = JUMP_SPEED
        this.onGround = false
        this.callbacks.onJump?.()
      }
    }

    const horizontalSpeed = Math.hypot(this.velocity.x, this.velocity.z)
    this.stepDistance += horizontalSpeed * dt
    if (this.onGround && this.stepDistance > (this.sprinting ? 2.1 : 1.9)) {
      this.stepDistance = 0
      this.callbacks.onStep?.()
    }

    const maxComponent = Math.max(Math.abs(this.velocity.x), Math.abs(this.velocity.y), Math.abs(this.velocity.z))
    const steps = Math.max(1, Math.min(8, Math.ceil((maxComponent * dt) / 0.22)))
    const stepDt = dt / steps
    this.onGround = false
    for (let i = 0; i < steps; i++) {
      this.moveAxis('x', this.velocity.x * stepDt)
      this.moveAxis('z', this.velocity.z * stepDt)
      this.moveAxis('y', this.velocity.y * stepDt)
    }

    if (this.position.y < -24) this.respawn()

    this.camera.position.set(this.position.x, this.position.y + EYE_HEIGHT, this.position.z)
    this.camera.rotation.set(this.pitch, this.yaw, 0, 'YXZ')
  }

  moveAxis(axis, amount) {
    if (amount === 0) return
    this.position[axis] += amount

    const minX = this.position.x - HALF_WIDTH
    const maxX = this.position.x + HALF_WIDTH
    const minY = this.position.y
    const maxY = this.position.y + HEIGHT
    const minZ = this.position.z - HALF_WIDTH
    const maxZ = this.position.z + HALF_WIDTH

    let limit = amount > 0 ? Infinity : -Infinity
    let hit = false

    const x0 = Math.floor(minX + 0.0001)
    const x1 = Math.floor(maxX - 0.0001)
    const y0 = Math.floor(minY + 0.0001)
    const y1 = Math.floor(maxY - 0.0001)
    const z0 = Math.floor(minZ + 0.0001)
    const z1 = Math.floor(maxZ - 0.0001)

    for (let bx = x0; bx <= x1; bx++) {
      for (let by = y0; by <= y1; by++) {
        for (let bz = z0; bz <= z1; bz++) {
          if (by < 0 || by >= WORLD_HEIGHT) continue
          if (!isSolid(this.world.getBlock(bx, by, bz))) continue
          hit = true
          if (axis === 'x') {
            if (amount > 0) limit = Math.min(limit, bx - HALF_WIDTH)
            else limit = Math.max(limit, bx + 1 + HALF_WIDTH)
          } else if (axis === 'z') {
            if (amount > 0) limit = Math.min(limit, bz - HALF_WIDTH)
            else limit = Math.max(limit, bz + 1 + HALF_WIDTH)
          } else {
            if (amount > 0) limit = Math.min(limit, by - HEIGHT)
            else {
              limit = Math.max(limit, by + 1)
              this.onGround = true
            }
          }
        }
      }
    }

    if (hit) {
      this.position[axis] = limit
      if (axis === 'y') {
        if (amount < 0 && this.velocity.y < 0) {
          if (this.velocity.y < -12) this.callbacks.onLand?.(this.velocity.y)
          this.velocity.y = 0
        } else if (amount > 0) {
          this.velocity.y = 0
        }
      } else {
        this.velocity[axis] = 0
      }
    }
  }

  getEyePosition(target = new THREE.Vector3()) {
    return target.set(this.position.x, this.position.y + EYE_HEIGHT, this.position.z)
  }

  getLookDirection(target = new THREE.Vector3()) {
    const cos = Math.cos(this.pitch)
    return target.set(-Math.sin(this.yaw) * cos, Math.sin(this.pitch), -Math.cos(this.yaw) * cos)
  }

  playerBoxIntersects(x, y, z) {
    return (
      x + 1 > this.position.x - HALF_WIDTH &&
      x < this.position.x + HALF_WIDTH &&
      y + 1 > this.position.y &&
      y < this.position.y + HEIGHT &&
      z + 1 > this.position.z - HALF_WIDTH &&
      z < this.position.z + HALF_WIDTH
    )
  }
}

import * as THREE from 'three'
import { FOG_FAR, FOG_NEAR } from './world.js'

const DAY_SECONDS = 480
const CLOUD_RANGE = 260

const vertexShader = /* glsl */ `
  varying vec3 vDir;
  void main() {
    vDir = normalize(position);
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
`

const fragmentShader = /* glsl */ `
  uniform vec3 uZenith;
  uniform vec3 uHorizon;
  uniform vec3 uGround;
  uniform vec3 uSunColor;
  uniform vec3 uSunDir;
  uniform float uNight;

  varying vec3 vDir;

  float hash(vec3 p) {
    p = fract(p * 0.3183099 + vec3(0.11, 0.17, 0.13));
    p *= 17.0;
    return fract(p.x * p.y * p.z * (p.x + p.y + p.z));
  }

  void main() {
    vec3 dir = normalize(vDir);
    float up = clamp(dir.y, -1.0, 1.0);
    vec3 col = mix(uHorizon, uZenith, pow(clamp(up, 0.0, 1.0), 0.55));
    col = mix(uGround, col, smoothstep(-0.22, 0.02, up));

    float sun = max(dot(dir, normalize(uSunDir)), 0.0);
    col += uSunColor * (pow(sun, 900.0) * 1.9 + pow(sun, 24.0) * 0.16 + pow(sun, 5.0) * 0.03);

    float star = step(0.9986, hash(floor(dir * 460.0))) * smoothstep(0.0, 0.22, up);
    col += vec3(0.85, 0.9, 1.0) * star * uNight * 0.9;

    gl_FragColor = vec4(col, 1.0);
  }
`

function makeSunTexture() {
  const canvas = document.createElement('canvas')
  canvas.width = canvas.height = 96
  const ctx = canvas.getContext('2d')
  const glow = ctx.createRadialGradient(48, 48, 8, 48, 48, 46)
  glow.addColorStop(0, 'rgba(255, 247, 205, 0.95)')
  glow.addColorStop(0.32, 'rgba(255, 226, 130, 0.55)')
  glow.addColorStop(0.6, 'rgba(255, 198, 90, 0.14)')
  glow.addColorStop(1, 'rgba(255, 180, 60, 0)')
  ctx.fillStyle = glow
  ctx.fillRect(0, 0, 96, 96)
  ctx.fillStyle = '#fff8d2'
  ctx.fillRect(33, 33, 30, 30)
  ctx.fillStyle = '#ffeaa2'
  ctx.fillRect(33, 33, 30, 3)
  ctx.fillRect(33, 33, 3, 30)
  const texture = new THREE.CanvasTexture(canvas)
  texture.colorSpace = THREE.SRGBColorSpace
  return texture
}

function makeMoonTexture() {
  const canvas = document.createElement('canvas')
  canvas.width = canvas.height = 96
  const ctx = canvas.getContext('2d')
  const glow = ctx.createRadialGradient(48, 48, 10, 48, 48, 44)
  glow.addColorStop(0, 'rgba(220, 235, 255, 0.55)')
  glow.addColorStop(0.5, 'rgba(180, 210, 255, 0.12)')
  glow.addColorStop(1, 'rgba(150, 190, 255, 0)')
  ctx.fillStyle = glow
  ctx.fillRect(0, 0, 96, 96)
  ctx.fillStyle = '#e7eefc'
  ctx.fillRect(34, 34, 28, 28)
  ctx.fillStyle = '#c3d0e8'
  ctx.fillRect(38, 39, 5, 5)
  ctx.fillRect(50, 48, 6, 6)
  ctx.fillRect(44, 54, 4, 4)
  const texture = new THREE.CanvasTexture(canvas)
  texture.colorSpace = THREE.SRGBColorSpace
  return texture
}

function smoothstep(edge0, edge1, x) {
  const t = Math.min(1, Math.max(0, (x - edge0) / (edge1 - edge0)))
  return t * t * (3 - 2 * t)
}

export class Sky {
  constructor(scene) {
    this.scene = scene
    this.time = 0.305
    this.day = 1
    this.cycleSeconds = DAY_SECONDS
    this.sunDirection = new THREE.Vector3(0, 1, 0)
    this.daylight = 1
    this.twilight = 0
    this.night = 0
    this.blockTint = new THREE.Color(1, 1, 1)
    this.waterTint = new THREE.Color(1, 1, 1)
    this.fogColor = new THREE.Color(0xbfe0f5)
    this.horizonColor = new THREE.Color(0xbfe0f5)
    this.cloudMaterial = null

    this.uniforms = {
      uZenith: { value: new THREE.Color(0x3f7fd6) },
      uHorizon: { value: new THREE.Color(0xbfe0f5) },
      uGround: { value: new THREE.Color(0x607d92) },
      uSunColor: { value: new THREE.Color(0xffe6a3) },
      uSunDir: { value: new THREE.Vector3(0, 1, 0) },
      uNight: { value: 0 }
    }

    const geometry = new THREE.SphereGeometry(500, 32, 20)
    const material = new THREE.ShaderMaterial({
      uniforms: this.uniforms,
      vertexShader,
      fragmentShader,
      side: THREE.BackSide,
      depthWrite: false,
      fog: false
    })
    this.sphere = new THREE.Mesh(geometry, material)
    this.sphere.frustumCulled = false
    this.sphere.renderOrder = -1000
    scene.add(this.sphere)

    this.sunSprite = new THREE.Sprite(
      new THREE.SpriteMaterial({
        map: makeSunTexture(),
        transparent: true,
        depthWrite: false,
        fog: false,
        blending: THREE.AdditiveBlending
      })
    )
    this.sunSprite.scale.setScalar(42)
    this.sunSprite.renderOrder = -900
    scene.add(this.sunSprite)

    this.moonSprite = new THREE.Sprite(
      new THREE.SpriteMaterial({
        map: makeMoonTexture(),
        transparent: true,
        depthWrite: false,
        fog: false
      })
    )
    this.moonSprite.scale.setScalar(32)
    this.moonSprite.renderOrder = -900
    scene.add(this.moonSprite)

    this.scene.fog = new THREE.Fog(0xbfe0f5, FOG_NEAR, FOG_FAR)

    this._createClouds()
    this.update(0, new THREE.Vector3(0, 40, 0))
  }

  _createClouds() {
    const geometry = new THREE.BoxGeometry(1, 1, 1)
    const material = new THREE.MeshBasicMaterial({
      color: 0xffffff,
      transparent: true,
      opacity: 0.72,
      depthWrite: false,
      fog: true
    })
    this.cloudMaterial = material
    this.clouds = []
    this.cloudDrift = 0

    let seed = 0x1f2e3d
    const random = () => {
      seed = (seed * 1103515245 + 12345) & 0x7fffffff
      return seed / 0x7fffffff
    }

    const count = 120
    const mesh = new THREE.InstancedMesh(geometry, material, count)
    mesh.frustumCulled = false
    mesh.renderOrder = 4
    mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage)
    this.cloudMesh = mesh
    this.scene.add(mesh)

    let index = 0
    while (index < count) {
      const clusterX = (random() * 2 - 1) * CLOUD_RANGE
      const clusterZ = (random() * 2 - 1) * CLOUD_RANGE
      const clusterY = 76 + random() * 18
      const pieces = 2 + Math.floor(random() * 3)
      for (let p = 0; p < pieces && index < count; p++) {
        this.clouds.push({
          x: clusterX + (random() * 2 - 1) * 15,
          y: clusterY + (random() * 2 - 1) * 1.8,
          z: clusterZ + (random() * 2 - 1) * 9,
          sx: 8 + random() * 16,
          sy: 1.4 + random() * 1.8,
          sz: 7 + random() * 11
        })
        index++
      }
    }
    this._writeCloudMatrices(0)
  }

  _writeCloudMatrices(cameraX, cameraZ) {
    const dummy = new THREE.Object3D()
    const range = CLOUD_RANGE * 2
    for (let i = 0; i < this.clouds.length; i++) {
      const cloud = this.clouds[i]
      let x = cloud.x + this.cloudDrift - cameraX
      let z = cloud.z - cameraZ
      x = ((x % range) + range) % range - range / 2 + cameraX
      z = ((z % range) + range) % range - range / 2 + cameraZ
      dummy.position.set(x, cloud.y, z)
      dummy.scale.set(cloud.sx, cloud.sy, cloud.sz)
      dummy.rotation.set(0, 0, 0)
      dummy.updateMatrix()
      this.cloudMesh.setMatrixAt(i, dummy.matrix)
    }
    this.cloudMesh.instanceMatrix.needsUpdate = true
  }

  update(dt, cameraPosition) {
    this.time += dt / this.cycleSeconds
    if (this.time >= 1) {
      this.time -= 1
      this.day++
    }

    const angle = (this.time - 0.25) * Math.PI * 2
    const elevation = Math.sin(angle)
    this.sunDirection.set(Math.cos(angle), elevation, 0.3).normalize()
    this.daylight = smoothstep(-0.1, 0.14, elevation)
    this.twilight = Math.exp(-Math.pow(elevation / 0.16, 2))
    this.night = 1 - smoothstep(-0.12, 0.05, elevation)

    const dayTop = CACHE.dayTop
    const dayHorizon = CACHE.dayHorizon
    const nightTop = CACHE.nightTop
    const nightHorizon = CACHE.nightHorizon
    const duskTop = CACHE.duskTop
    const duskHorizon = CACHE.duskHorizon

    CACHE.top.copy(nightTop).lerp(dayTop, this.daylight)
    CACHE.top.lerp(duskTop, this.twilight * 0.55 * (0.35 + this.daylight * 0.65))
    CACHE.horizon.copy(nightHorizon).lerp(dayHorizon, this.daylight)
    CACHE.horizon.lerp(duskHorizon, this.twilight * 0.9)

    this.uniforms.uZenith.value.copy(CACHE.top)
    this.uniforms.uHorizon.value.copy(CACHE.horizon)
    this.uniforms.uGround.value.copy(CACHE.horizon).multiplyScalar(0.62)
    this.uniforms.uSunDir.value.copy(this.sunDirection)
    this.uniforms.uNight.value = this.night
    this.uniforms.uSunColor.value.setRGB(
      1.0,
      0.82 + this.daylight * 0.12,
      0.62 + this.daylight * 0.3
    )

    this.fogColor.copy(CACHE.horizon)
    this.horizonColor.copy(CACHE.horizon)
    this.scene.fog.color.copy(this.horizonColor)

    const warm = this.twilight * 0.16 * (0.4 + this.daylight * 0.6)
    this.blockTint.setRGB(
      0.3 + 0.7 * this.daylight + warm,
      0.37 + 0.63 * this.daylight + warm * 0.55,
      0.58 + 0.42 * this.daylight
    )
    this.waterTint.copy(this.blockTint)

    this.cloudMaterial.color.setRGB(
      0.45 + 0.55 * this.daylight + warm,
      0.52 + 0.48 * this.daylight + warm * 0.5,
      0.72 + 0.28 * this.daylight
    )
    this.cloudMaterial.opacity = 0.28 + 0.48 * this.daylight

    if (cameraPosition) {
      this.sphere.position.copy(cameraPosition)
      this.sunSprite.position
        .copy(cameraPosition)
        .addScaledVector(this.sunDirection, 340)
      this.moonSprite.position
        .copy(cameraPosition)
        .addScaledVector(this.sunDirection, -340)
      this.sunSprite.visible = this.sunDirection.y > -0.12
      this.moonSprite.visible = this.sunDirection.y < 0.12
      this.cloudDrift += dt * 1.8
      this._writeCloudMatrices(cameraPosition.x, cameraPosition.z)
    }
  }

  get clockLabel() {
    const totalMinutes = Math.floor(this.time * 24 * 60)
    const hours = Math.floor(totalMinutes / 60)
    const minutes = totalMinutes % 60
    return `Day ${this.day} · ${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}`
  }
}

const CACHE = {
  top: new THREE.Color(),
  horizon: new THREE.Color(),
  dayTop: new THREE.Color(0x3d7cd4),
  dayHorizon: new THREE.Color(0xc7e3f6),
  nightTop: new THREE.Color(0x050a18),
  nightHorizon: new THREE.Color(0x0f1c36),
  duskTop: new THREE.Color(0x53639b),
  duskHorizon: new THREE.Color(0xff9d5c)
}

// Tiny procedural sound kit. Everything is synthesized with WebAudio so the
// game ships with zero audio assets.
export class SoundKit {
  constructor() {
    this.ctx = null
    this.master = null
    this.noise = null
    this.muted = false
    this.lastStep = 0
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {})
      return
    }
    const AudioContextClass = window.AudioContext || window.webkitAudioContext
    if (!AudioContextClass) return
    try {
      this.ctx = new AudioContextClass()
      this.master = this.ctx.createGain()
      this.master.gain.value = 0.22
      this.master.connect(this.ctx.destination)
      const length = Math.floor(this.ctx.sampleRate * 0.35)
      this.noise = this.ctx.createBuffer(1, length, this.ctx.sampleRate)
      const data = this.noise.getChannelData(0)
      for (let i = 0; i < length; i++) data[i] = Math.random() * 2 - 1
    } catch {
      this.ctx = null
    }
  }

  toggleMute() {
    this.muted = !this.muted
    if (this.master) this.master.gain.value = this.muted ? 0 : 0.22
    return this.muted
  }

  _ready() {
    return this.ctx && !this.muted && this.ctx.state === 'running'
  }

  _noiseBurst({ duration = 0.12, frequency = 900, q = 1.2, volume = 0.5, filterType = 'bandpass' }) {
    if (!this._ready()) return
    const now = this.ctx.currentTime
    const source = this.ctx.createBufferSource()
    source.buffer = this.noise
    const filter = this.ctx.createBiquadFilter()
    filter.type = filterType
    filter.frequency.setValueAtTime(frequency, now)
    filter.frequency.exponentialRampToValueAtTime(Math.max(80, frequency * 0.35), now + duration)
    filter.Q.value = q
    const gain = this.ctx.createGain()
    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.001, now + duration)
    source.connect(filter)
    filter.connect(gain)
    gain.connect(this.master)
    source.start(now)
    source.stop(now + duration + 0.02)
  }

  _tone({ frequency = 220, endFrequency = 120, duration = 0.12, volume = 0.2, type = 'triangle' }) {
    if (!this._ready()) return
    const now = this.ctx.currentTime
    const osc = this.ctx.createOscillator()
    const gain = this.ctx.createGain()
    osc.type = type
    osc.frequency.setValueAtTime(frequency, now)
    osc.frequency.exponentialRampToValueAtTime(Math.max(40, endFrequency), now + duration)
    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.001, now + duration)
    osc.connect(gain)
    gain.connect(this.master)
    osc.start(now)
    osc.stop(now + duration + 0.02)
  }

  breakBlock(block) {
    const hardness = block?.liquid ? 0.2 : 1
    this._noiseBurst({
      duration: 0.12 + hardness * 0.05,
      frequency: 700 + Math.random() * 500,
      q: 0.9,
      volume: 0.45
    })
    this._tone({ frequency: 150 + Math.random() * 60, endFrequency: 70, duration: 0.1, volume: 0.22 })
  }

  placeBlock() {
    this._tone({ frequency: 240, endFrequency: 140, duration: 0.07, volume: 0.2, type: 'square' })
    this._noiseBurst({ duration: 0.06, frequency: 1200, q: 1.5, volume: 0.18 })
  }

  step() {
    const now = performance.now()
    if (now - this.lastStep < 150) return
    this.lastStep = now
    this._noiseBurst({ duration: 0.05, frequency: 340 + Math.random() * 220, q: 0.8, volume: 0.12, filterType: 'lowpass' })
  }

  jump() {
    this._tone({ frequency: 320, endFrequency: 180, duration: 0.09, volume: 0.1 })
  }

  land() {
    this._noiseBurst({ duration: 0.09, frequency: 220, q: 0.7, volume: 0.2, filterType: 'lowpass' })
  }
}

import * as THREE from 'three'

const MAX_PARTICLES = 420

export class Particles {
  constructor(scene) {
    this.positions = new Float32Array(MAX_PARTICLES * 3)
    this.colors = new Float32Array(MAX_PARTICLES * 3)
    this.velocity = new Float32Array(MAX_PARTICLES * 3)
    this.life = new Float32Array(MAX_PARTICLES)
    this.maxLife = new Float32Array(MAX_PARTICLES)
    this.cursor = 0

    for (let i = 0; i < MAX_PARTICLES; i++) {
      this.positions[i * 3 + 1] = -999
    }

    const geometry = new THREE.BufferGeometry()
    geometry.setAttribute('position', new THREE.BufferAttribute(this.positions, 3))
    geometry.setAttribute('color', new THREE.BufferAttribute(this.colors, 3))
    geometry.boundingSphere = new THREE.Sphere(new THREE.Vector3(), 1000000)

    const material = new THREE.PointsMaterial({
      size: 0.14,
      vertexColors: true,
      sizeAttenuation: true,
      transparent: true,
      opacity: 0.95,
      depthWrite: false
    })
    this.points = new THREE.Points(geometry, material)
    this.points.frustumCulled = false
    this.points.renderOrder = 5
    scene.add(this.points)
  }

  spawn(x, y, z, color, count = 16) {
    for (let i = 0; i < count; i++) {
      const index = this.cursor
      this.cursor = (this.cursor + 1) % MAX_PARTICLES
      const jitter = 0.25
      this.positions[index * 3] = x + 0.5 + (Math.random() - 0.5) * jitter
      this.positions[index * 3 + 1] = y + 0.5 + (Math.random() - 0.5) * jitter
      this.positions[index * 3 + 2] = z + 0.5 + (Math.random() - 0.5) * jitter
      this.velocity[index * 3] = (Math.random() - 0.5) * 4.2
      this.velocity[index * 3 + 1] = Math.random() * 4 + 1.2
      this.velocity[index * 3 + 2] = (Math.random() - 0.5) * 4.2
      const shade = 0.72 + Math.random() * 0.4
      this.colors[index * 3] = color[0] * shade
      this.colors[index * 3 + 1] = color[1] * shade
      this.colors[index * 3 + 2] = color[2] * shade
      this.maxLife[index] = 0.55 + Math.random() * 0.45
      this.life[index] = this.maxLife[index]
    }
    this.points.geometry.attributes.color.needsUpdate = true
  }

  update(dt) {
    let alive = false
    for (let i = 0; i < MAX_PARTICLES; i++) {
      if (this.life[i] <= 0) continue
      alive = true
      this.life[i] -= dt
      if (this.life[i] <= 0) {
        this.positions[i * 3 + 1] = -999
        continue
      }
      this.velocity[i * 3 + 1] -= 18 * dt
      const drag = Math.exp(-1.4 * dt)
      this.velocity[i * 3] *= drag
      this.velocity[i * 3 + 2] *= drag
      this.positions[i * 3] += this.velocity[i * 3] * dt
      this.positions[i * 3 + 1] += this.velocity[i * 3 + 1] * dt
      this.positions[i * 3 + 2] += this.velocity[i * 3 + 2] * dt
    }
    if (alive) this.points.geometry.attributes.position.needsUpdate = true
  }

  clear() {
    for (let i = 0; i < MAX_PARTICLES; i++) {
      this.life[i] = 0
      this.positions[i * 3 + 1] = -999
    }
    this.points.geometry.attributes.position.needsUpdate = true
  }
}

import * as THREE from 'three'
import './styles.css'
import { createAtlas } from './textures.js'
import { World, RENDER_DISTANCE } from './world.js'
import { Sky } from './sky.js'
import { Player } from './player.js'
import { SoundKit } from './audio.js'
import { Particles } from './particles.js'
import {
  AIR,
  WATER,
  BEDROCK,
  BLOCKS,
  HOTBAR,
  isLiquid
} from './blocks.js'
import { CHUNK_SIZE, WORLD_HEIGHT, SEA_LEVEL } from './worldgen.js'

const SAVE_KEY = 'voxelcraft.save.v1'
const URL_PARAMS = new URLSearchParams(location.search)

const canvas = document.getElementById('game')
const menuElement = document.getElementById('menu')
const loadingElement = document.getElementById('loading')
const pauseElement = document.getElementById('pause')
const hudElement = document.getElementById('hud')
const touchElement = document.getElementById('touch-controls')
const progressFill = document.getElementById('progress-fill')
const loadingText = document.querySelector('.loading-text')
const seedValue = document.getElementById('seed-value')
const statsElement = document.getElementById('stats')
const clockText = document.getElementById('clock-text')
const blockLabel = document.getElementById('block-label')
const hotbarElement = document.getElementById('hotbar')
const waterOverlay = document.getElementById('water-overlay')
const modeBadge = document.getElementById('mode-badge')

const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  powerPreference: 'high-performance'
})
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2))
renderer.setSize(window.innerWidth, window.innerHeight)
renderer.setClearColor(0xbfe0f5, 1)

const scene = new THREE.Scene()
const camera = new THREE.PerspectiveCamera(72, window.innerWidth / window.innerHeight, 0.1, 1200)
camera.position.set(0, 60, 0)

const atlas = createAtlas()
const sound = new SoundKit()

let world
let sky
let player
let particles
let started = false
let paused = false
let isTouch = false
let selected = 0
let target = null
let save = null
let labelTimeout = null
let lastBreak = 0
let lastPlace = 0
let mining = false
let building = false
let fps = 60
let statsTimer = 0
let clockTimer = 0
let saveTimer = 0
let lastFrame = performance.now()
let dragLook = null
let lookPointer = null
let touchJumpTimeout = null
let lastJumpTap = 0
let foundSeed = null

const highlight = new THREE.LineSegments(
  new THREE.EdgesGeometry(new THREE.BoxGeometry(1.004, 1.004, 1.004)),
  new THREE.LineBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.85, depthTest: true })
)
highlight.visible = false
highlight.renderOrder = 3
scene.add(highlight)

const eye = new THREE.Vector3()
const lookDirection = new THREE.Vector3()

init().catch((error) => {
  console.error(error)
  loadingText.textContent = 'Could not start the world. Reload to try again.'
})

async function init() {
  save = loadSave()
  const urlSeed = URL_PARAMS.get('seed')
  const seed = urlSeed !== null ? Number(urlSeed) >>> 0 : save?.seed ?? randomSeed()
  foundSeed = seed

  world = new World(scene, atlas, seed, save?.edits || [])
  sky = new Sky(scene)
  particles = new Particles(scene)
  player = new Player(world, camera, canvas)
  player.callbacks = {
    onStep: () => sound.step(),
    onJump: () => sound.jump(),
    onLand: () => sound.land(),
    onFly: (flying) => {
      modeBadge.textContent = flying ? 'creative · flying' : 'creative'
      toast(flying ? 'Flying enabled' : 'Flying disabled')
    }
  }

  buildHotbar()
  updateTouchMode()
  window.addEventListener('resize', onResize)
  window.addEventListener('resize', updateTouchMode)
  bindInput()

  if (loadingElement) loadingElement.classList.remove('hidden')
  await world.preload((progress) => {
    progressFill.style.width = `${Math.round(progress)}%`
    if (progress > 56) loadingText.textContent = 'Building chunks…'
    else if (progress > 20) loadingText.textContent = 'Planting forests…'
  })

  const spawn = world.spawn
  const savedPlayer = save?.player
  if (savedPlayer && Number.isFinite(savedPlayer.x) && savedPlayer.y > 0) {
    player.spawn = {
      x: savedPlayer.x,
      y: savedPlayer.y,
      z: savedPlayer.z,
      yaw: savedPlayer.yaw ?? spawn.yaw,
      pitch: savedPlayer.pitch ?? -0.07
    }
    player.respawn()
  } else {
    const feetY = spawn.height + 1
    world.clearSpawnArea(spawn.x, feetY, spawn.z, 2, 6)
    player.setSpawn(spawn.x, feetY, spawn.z, spawn.yaw, spawn.pitch)
  }

  if (save?.time !== undefined) sky.time = save.time
  if (save?.day !== undefined) sky.day = save.day
  if (save?.selected !== undefined) selected = Math.min(HOTBAR.length - 1, Math.max(0, save.selected))

  updateSelection(selected, false)
  seedValue.textContent = String(seed)
  sky.update(0, camera.position)
  applySkyTint()
  syncCamera()

  loadingElement.classList.add('hidden')
  menuElement.classList.remove('hidden')

  const isNew = !save
  if (isNew) {
    // Make sure the first frame behind the menu is already lit correctly.
    world.update(player.position.x, player.position.z, 8)
  }

  requestAnimationFrame(loop)
}

function randomSeed() {
  return (Math.random() * 1_000_000_000) | 0
}

function loadSave() {
  try {
    const raw = localStorage.getItem(SAVE_KEY)
    if (!raw) return null
    const data = JSON.parse(raw)
    if (!data || typeof data.seed !== 'number') return null
    return data
  } catch {
    return null
  }
}

function persist() {
  if (!started || !world || !sky || !player) return
  try {
    localStorage.setItem(
      SAVE_KEY,
      JSON.stringify({
        version: 1,
        seed: world.seed,
        edits: world.serializeEdits(),
        player: {
          x: player.position.x,
          y: player.position.y,
          z: player.position.z,
          yaw: player.yaw,
          pitch: player.pitch
        },
        time: sky.time,
        day: sky.day,
        selected
      })
    )
  } catch {
    // Storage is a nice-to-have; ignore quota or privacy errors.
  }
}

function newWorld() {
  localStorage.removeItem(SAVE_KEY)
  const url = new URL(location.href)
  url.searchParams.set('seed', String(randomSeed()))
  location.href = url.toString()
}

function buildHotbar() {
  hotbarElement.innerHTML = ''
  HOTBAR.forEach((blockId, index) => {
    const slot = document.createElement('button')
    slot.className = 'slot'
    slot.type = 'button'
    slot.setAttribute('aria-label', BLOCKS[blockId].name)
    const icon = atlas.createIcon(blockId, 64)
    slot.appendChild(icon)
    const number = document.createElement('span')
    number.className = 'num'
    number.textContent = String(index + 1)
    slot.appendChild(number)
    slot.addEventListener('pointerdown', (event) => {
      event.stopPropagation()
      event.preventDefault()
      updateSelection(index, true)
    })
    hotbarElement.appendChild(slot)
  })
}

function updateSelection(index, announce = true) {
  selected = ((index % HOTBAR.length) + HOTBAR.length) % HOTBAR.length
  const slots = hotbarElement.children
  for (let i = 0; i < slots.length; i++) slots[i].classList.toggle('selected', i === selected)
  if (announce) toast(BLOCKS[HOTBAR[selected]].name)
}

function toast(text) {
  blockLabel.textContent = text
  blockLabel.classList.add('show')
  clearTimeout(labelTimeout)
  labelTimeout = setTimeout(() => blockLabel.classList.remove('show'), 1400)
}

function updateTouchMode() {
  const coarse = window.matchMedia?.('(pointer: coarse)').matches
  isTouch = Boolean(coarse || navigator.maxTouchPoints > 0 || window.innerWidth <= 820)
  document.body.classList.toggle('touch', isTouch)
  touchElement.classList.toggle('hidden', !(isTouch && started && !paused))
}

function onResize() {
  camera.aspect = window.innerWidth / window.innerHeight
  camera.updateProjectionMatrix()
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2))
  renderer.setSize(window.innerWidth, window.innerHeight)
}

function syncCamera() {
  camera.position.set(player.position.x, player.position.y + 1.62, player.position.z)
  camera.rotation.set(player.pitch, player.yaw, 0, 'YXZ')
}

function startGame() {
  if (started) return
  started = true
  sound.init()
  menuElement.classList.add('hidden')
  hudElement.classList.remove('hidden')
  player.enabled = true
  updateTouchMode()
  syncCamera()
  requestPointerLock()
  toast('Welcome to VoxelCraft')
  // Prime the target ray so the first click feels immediate.
  updateTarget()
}

function requestPointerLock() {
  if (isTouch || paused) return
  try {
    const result = canvas.requestPointerLock?.()
    if (result && typeof result.catch === 'function') result.catch(() => {})
  } catch {
    // Pointer lock can be denied; drag-to-look still works.
  }
}

function pauseGame() {
  if (!started || paused) return
  paused = true
  player.enabled = false
  mining = false
  building = false
  document.exitPointerLock?.()
  pauseElement.classList.remove('hidden')
  touchElement.classList.add('hidden')
  persist()
}

function resumeGame() {
  if (!started || !paused) return
  paused = false
  player.enabled = true
  pauseElement.classList.add('hidden')
  updateTouchMode()
  sound.init()
  requestPointerLock()
}

function setSelectedByWheel(direction) {
  updateSelection(selected + direction, true)
}

function bindInput() {
  document.getElementById('play-btn').addEventListener('click', startGame)
  document.getElementById('newworld-btn').addEventListener('click', newWorld)
  document.getElementById('newworld-btn-2').addEventListener('click', newWorld)
  document.getElementById('resume-btn').addEventListener('click', resumeGame)

  window.addEventListener('keydown', (event) => {
    if (event.code === 'Escape') {
      if (started) {
        if (paused) resumeGame()
        else pauseGame()
      }
      return
    }
    if (!started || paused) return

    if (event.code.startsWith('Digit')) {
      const digit = Number(event.code.slice(5))
      if (digit >= 1 && digit <= HOTBAR.length) updateSelection(digit - 1)
    }
    if (event.code === 'KeyM') {
      const muted = sound.toggleMute()
      toast(muted ? 'Sound muted' : 'Sound on')
    }
  })

  window.addEventListener('wheel', (event) => {
    if (!started || paused) return
    if (Math.abs(event.deltaY) < 2) return
    setSelectedByWheel(event.deltaY > 0 ? 1 : -1)
  }, { passive: true })

  canvas.addEventListener('contextmenu', (event) => event.preventDefault())

  canvas.addEventListener('pointerdown', (event) => {
    if (!started || paused) return
    sound.init()

    if (event.pointerType === 'touch') {
      lookPointer = { id: event.pointerId, x: event.clientX, y: event.clientY }
      canvas.setPointerCapture?.(event.pointerId)
      event.preventDefault()
      return
    }

    if (document.pointerLockElement === canvas) {
      if (event.button === 0) {
        mining = true
        breakTarget()
      } else if (event.button === 2) {
        building = true
        placeTarget()
      }
      return
    }

    dragLook = {
      button: event.button,
      x: event.clientX,
      y: event.clientY,
      lastX: event.clientX,
      lastY: event.clientY,
      moved: false
    }
  })

  canvas.addEventListener('pointermove', (event) => {
    if (!started || paused) return
    if (event.pointerType === 'touch') {
      if (lookPointer && lookPointer.id === event.pointerId) {
        const dx = event.clientX - lookPointer.x
        const dy = event.clientY - lookPointer.y
        lookPointer.x = event.clientX
        lookPointer.y = event.clientY
        player.look(dx, dy, 0.0042)
      }
      return
    }

    if (document.pointerLockElement === canvas) {
      player.look(event.movementX || 0, event.movementY || 0, 0.0022)
      return
    }

    if (dragLook) {
      const dx = event.clientX - dragLook.lastX
      const dy = event.clientY - dragLook.lastY
      if (Math.abs(event.clientX - dragLook.x) + Math.abs(event.clientY - dragLook.y) > 4) {
        dragLook.moved = true
      }
      if (dragLook.moved) player.look(dx, dy, 0.0032)
      dragLook.lastX = event.clientX
      dragLook.lastY = event.clientY
    }
  })

  const endPointer = (event) => {
    if (event.pointerType === 'touch') {
      if (lookPointer && lookPointer.id === event.pointerId) lookPointer = null
      return
    }
    if (document.pointerLockElement === canvas) {
      if (event.button === 0) mining = false
      if (event.button === 2) building = false
      return
    }
    if (dragLook) {
      const wasDrag = dragLook
      dragLook = null
      if (!wasDrag.moved) {
        if (wasDrag.button === 0) breakTarget()
        else if (wasDrag.button === 2) placeTarget()
      }
    }
  }
  canvas.addEventListener('pointerup', endPointer)
  canvas.addEventListener('pointercancel', endPointer)

  document.addEventListener('pointerlockchange', () => {
    if (!started || paused) return
    if (document.pointerLockElement !== canvas && !isTouch) {
      // Clicking the canvas returns to mouse-look when the lock was lost.
      mining = false
      building = false
    }
  })

  // Touch controls ------------------------------------------------------
  const joystick = document.getElementById('joystick')
  const knob = document.getElementById('joystick-knob')
  const jumpButton = document.getElementById('btn-jump')
  const breakButton = document.getElementById('btn-break')
  const placeButton = document.getElementById('btn-place')
  let joyPointer = null
  let joyCenter = { x: 0, y: 0, radius: 1 }

  joystick.addEventListener('pointerdown', (event) => {
    if (!started || paused) return
    event.preventDefault()
    event.stopPropagation()
    joystick.classList.add('active')
    const rect = joystick.getBoundingClientRect()
    joyCenter = { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2, radius: rect.width * 0.34 }
    joyPointer = event.pointerId
    joystick.setPointerCapture?.(event.pointerId)
    updateJoystick(event)
  })

  function updateJoystick(event) {
    if (joyPointer !== event.pointerId) return
    let dx = event.clientX - joyCenter.x
    let dy = event.clientY - joyCenter.y
    const length = Math.hypot(dx, dy)
    if (length > joyCenter.radius) {
      dx = (dx / length) * joyCenter.radius
      dy = (dy / length) * joyCenter.radius
    }
    knob.style.transform = `translate(${dx}px, ${dy}px)`
    player.setJoystick(dx / joyCenter.radius, -dy / joyCenter.radius)
  }

  joystick.addEventListener('pointermove', updateJoystick)
  const endJoystick = (event) => {
    if (joyPointer !== event.pointerId) return
    joyPointer = null
    joystick.classList.remove('active')
    knob.style.transform = 'translate(0px, 0px)'
    player.setJoystick(0, 0)
  }
  joystick.addEventListener('pointerup', endJoystick)
  joystick.addEventListener('pointercancel', endJoystick)

  jumpButton.addEventListener('pointerdown', (event) => {
    if (!started || paused) return
    event.preventDefault()
    sound.init()
    player.touchJump = true
    jumpButton.classList.add('pressed')
    const now = performance.now()
    if (now - lastJumpTap < 300) {
      player.toggleFly()
      lastJumpTap = 0
    } else {
      lastJumpTap = now
    }
    clearTimeout(touchJumpTimeout)
    touchJumpTimeout = setTimeout(() => {
      player.touchJump = false
      jumpButton.classList.remove('pressed')
    }, 180)
  })
  const stopJump = () => {
    player.touchJump = false
    jumpButton.classList.remove('pressed')
  }
  jumpButton.addEventListener('pointerup', stopJump)
  jumpButton.addEventListener('pointercancel', stopJump)
  jumpButton.addEventListener('pointerleave', stopJump)

  const startHold = (button, action) => {
    if (!started || paused) return
    eventPrevent(button)
    sound.init()
    action()
    button.classList.add('pressed')
  }
  breakButton.addEventListener('pointerdown', () => {
    if (!started || paused) return
    mining = true
    breakButton.classList.add('pressed', 'holding')
    breakTarget()
  })
  const stopBreak = () => {
    mining = false
    breakButton.classList.remove('pressed', 'holding')
  }
  breakButton.addEventListener('pointerup', stopBreak)
  breakButton.addEventListener('pointercancel', stopBreak)
  breakButton.addEventListener('pointerleave', stopBreak)

  placeButton.addEventListener('pointerdown', () => {
    if (!started || paused) return
    building = true
    placeButton.classList.add('pressed')
    placeTarget()
  })
  const stopPlace = () => {
    building = false
    placeButton.classList.remove('pressed')
  }
  placeButton.addEventListener('pointerup', stopPlace)
  placeButton.addEventListener('pointercancel', stopPlace)
  placeButton.addEventListener('pointerleave', stopPlace)

  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'hidden') persist()
  })
  window.addEventListener('beforeunload', persist)

  setInterval(persist, 12000)
}

function eventPrevent(element) {
  element.addEventListener('contextmenu', (event) => event.preventDefault())
}

function updateTarget() {
  if (!started || paused) {
    highlight.visible = false
    return
  }
  player.getEyePosition(eye)
  player.getLookDirection(lookDirection)
  target = world.raycast(eye, lookDirection, 7)
  if (target) {
    highlight.visible = true
    highlight.position.set(target.x + 0.5, target.y + 0.5, target.z + 0.5)
  } else {
    highlight.visible = false
  }
}

function breakTarget() {
  const now = performance.now()
  if (now - lastBreak < 170) return
  updateTarget()
  if (!target) return
  const { x, y, z, block } = target
  if (block === BEDROCK) {
    toast('Bedrock is unbreakable')
    return
  }
  lastBreak = now
  world.setBlock(x, y, z, AIR)
  const def = BLOCKS[block]
  if (def) {
    particles.spawn(x, y, z, def.color, 18)
    sound.breakBlock(def)
  }
  updateTarget()
}

function placeTarget() {
  const now = performance.now()
  if (now - lastPlace < 200) return
  updateTarget()
  if (!target) return
  const px = target.x + target.normal[0]
  const py = target.y + target.normal[1]
  const pz = target.z + target.normal[2]
  if (py < 0 || py >= WORLD_HEIGHT) return
  const current = world.getBlock(px, py, pz)
  if (current !== AIR && !isLiquid(current)) return
  if (player.playerBoxIntersects(px, py, pz)) return

  const blockId = HOTBAR[selected]
  if (!world.setBlock(px, py, pz, blockId)) return
  lastPlace = now
  const def = BLOCKS[blockId]
  sound.placeBlock()
  particles.spawn(px, py, pz, def.color, 5)
  updateTarget()
}

function applySkyTint() {
  world.solidMaterial.color.copy(sky.blockTint)
  world.waterMaterial.color.copy(sky.waterTint)
  highlight.material.color.setRGB(
    0.85 + sky.daylight * 0.15,
    0.9 + sky.daylight * 0.1,
    0.85 + sky.daylight * 0.15
  )
}

function updateHud(dt) {
  statsTimer += dt
  clockTimer += dt
  if (statsTimer > 0.2) {
    statsTimer = 0
    const x = Math.floor(player.position.x)
    const y = Math.floor(player.position.y)
    const z = Math.floor(player.position.z)
    const mode = player.flying ? 'flying' : 'creative'
    statsElement.textContent = `x ${x}   y ${y}   z ${z}   ·   ${Math.round(fps)} fps   ·   ${mode}`
    modeBadge.textContent = player.flying ? 'creative · flying' : 'creative'
  }
  if (clockTimer > 0.6) {
    clockTimer = 0
    clockText.textContent = sky.clockLabel
  }
  const underwater = started && !paused && player.headInWater
  waterOverlay.classList.toggle('active', Boolean(underwater))
}

function loop(now) {
  const dt = Math.min(0.05, Math.max(0, (now - lastFrame) / 1000))
  lastFrame = now
  fps = fps * 0.92 + (1 / Math.max(dt, 0.0001)) * 0.08

  if (started && !paused) {
    player.update(dt)
  }

  if (started && !paused) {
    sky.update(dt, camera.position)
    world.update(player.position.x, player.position.z, 6)
    applySkyTint()
    updateTarget()

    if (mining && performance.now() - lastBreak >= 190) breakTarget()
    if (building && performance.now() - lastPlace >= 220) placeTarget()

    particles.update(dt)
    updateHud(dt)
  } else {
    // Keep the world warmed up behind the menu and pause screen.
    world.update(player.position.x, player.position.z, 5)
    particles.update(dt)
    if (!started) sky.update(0, camera.position)
  }

  renderer.render(scene, camera)
  requestAnimationFrame(loop)
}

window.addEventListener('error', (event) => {
  if (loadingElement && !loadingElement.classList.contains('hidden')) {
    console.error(event.error || event.message)
  }
})

