      const wx = Math.round(8 + Math.cos(angle) * radius)
      const wz = Math.round(8 + Math.sin(angle) * radius)
      const info = column(wx, wz)
      if (info.height < SEA_LEVEL + 2 || info.height > SEA_LEVEL + 9) continue
      if (info.biome === BIOME.DESERT) continue

      let min = 999
      let max = -999
      for (let dz = -3; dz <= 3; dz += 3) {
        for (let dx = -3; dx <= 3; dx += 3) {
          const h = column(wx + dx, wz + dz).height
          if (h < min) min = h
          if (h > max) max = h
        }
      }
      if (max - min > 5) continue
      if (min < SEA_LEVEL) continue
      best = { x: wx, z: wz, height: info.height, biome: info.biome }
      break
    }
