  let bestYaw = 0
  let bestScore = Infinity
  for (let i = 0; i < 16; i++) {
    const angle = (i / 16) * Math.PI * 2
    const dx = Math.cos(angle)
    const dz = Math.sin(angle)
    let score = 0
    for (const distance of [12, 24, 38]) {
      const h = column(Math.round(best.x + dx * distance), Math.round(best.z + dz * distance)).height
      score += h
    }
