function createIcon(blockId, size = 32) {
  const block = BLOCKS[blockId]
  const icon = document.createElement('canvas')
  icon.width = size
  icon.height = size
  const ictx = icon.getContext('2d')
  ictx.imageSmoothingEnabled = false
  if (blockId === GLASS) {
    // subtle checker so the transparent pane reads on the dark hotbar
    for (let y = 0; y < size; y += 4) {
      for (let x = 0; x < size; x += 4) {
        ictx.fillStyle = (x / 4 + y / 4) % 2 === 0 ? 'rgba(255,255,255,0.07)' : 'rgba(255,255,255,0.02)'
        ictx.fillRect(x, y, 4, 4)
      }
    }
  }
  const tile = tileFor(block, blockId === GLASS ? 0 : 2)
  const sx = (tile % COLS) * TILE_SIZE
  const sy = Math.floor(tile / COLS) * TILE_SIZE
  ictx.drawImage(canvas, sx, sy, TILE_SIZE, TILE_SIZE, 0, 0, size, size)
  return icon
}

